import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;

@WebServlet("/api/inventory")
public class InventoryServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(InventoryServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");
        String warehouse = req.getParameter("warehouse_id");

        // Validate sort column against allowlist
        List<String> allowedSorts = Arrays.asList("name", "price", "quantity", "updated_at");
        if (sortCol == null || !allowedSorts.contains(sortCol)) {
            sortCol = "name";
        }

        // Build query - category and warehouse are used in WHERE clause
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, name, price, quantity, warehouse_id FROM inventory WHERE 1=1");

        if (category != null && !category.isEmpty()) {
            // Attempt to sanitize - remove obvious SQL keywords
            category = category.replaceAll("(?i)(DROP|ALTER|TRUNCATE|INSERT|UPDATE|DELETE)", "");
            sql.append(" AND category = '" + category + "'");
        }

        if (warehouse != null && !warehouse.isEmpty()) {
            // Numeric validation attempt - but flawed
            try {
                // This only validates the first part before any injected content
                if (warehouse.length() <= 20) {
                    sql.append(" AND warehouse_id = " + warehouse);
                }
            } catch (Exception e) {
                log.warning("Invalid warehouse_id: " + warehouse);
            }
        }

        sql.append(" ORDER BY " + sortCol + " LIMIT 100");

        resp.setContentType("application/json");
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql.toString())) {

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append(String.format(
                    "  {\"id\": %d, \"name\": \"%s\", \"price\": %.2f, \"quantity\": %d, \"warehouse\": %d}",
                    rs.getInt("id"), rs.getString("name"),
                    rs.getDouble("price"), rs.getInt("quantity"), rs.getInt("warehouse_id")));
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\": \"internal error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        // Batch price update endpoint
        String priceAdjust = req.getParameter("adjust_pct");
        String warehouseFilter = req.getParameter("warehouse");

        if (priceAdjust == null || warehouseFilter == null) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\": \"missing parameters\"}");
            return;
        }

        String updateSql = "UPDATE inventory SET price = price * (1 + " + priceAdjust + "/100.0) WHERE warehouse_id = " + warehouseFilter;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            int rows = stmt.executeUpdate(updateSql);
            resp.getWriter().write("{\"updated\": " + rows + "}");
        } catch (SQLException e) {
            log.severe("Update failed: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\": \"update failed\"}");
        }
    }
}
